-- Промысловая мера во всех бассейнах. До сих пор в приложении была мера только Балхаш-Алакольского
-- бассейна (миграция …_rules.sql), а приказ № 78 (…_rules_kazakhstan.sql) мер не содержит: они — в
-- приложении 1 Правил рыболовства (приказ и. о. Министра сельского хозяйства РК от 27 февраля 2015 года
-- № 18-04/148). Текст сверен на adilet.zan.kz 10 ноября 2026 года.
--
-- Мера своя у Павлодарской области (в зоне irtysh_east_waters она вместе с ВКО и областью Абай) и у
-- Верхнетобольского и Каратомарского водохранилищ (в зоне kostanay_waters), поэтому им — свои зоны,
-- вырезанные из прежних. Запреты прежних зон переходят и на новые: сроки там те же. Границы — из
-- OpenStreetMap (© участники OpenStreetMap, ODbL), как они получены — supabase/data/rules
-- (fetch_osm_min_sizes.sh, zones_min_sizes.sql).
--
-- В min_sizes — только виды из справочника рыб; остальные (шемая, белоглазка, вобла, ряпушка, пелядь,
-- раки…) — в тексте правила. Мера щуки в Нура-Сарысуском бассейне — для любительского лова (25 см).
-- Казахские названия рыб — черновик на вычитку.

-- Новые зоны ---------------------------------------------------------------------------------------

insert into public.rule_zones (id, kind, basin, name_ru, name_kk, name_en, note_ru, note_kk, note_en, sort_order) values
  ('pavlodar_waters', 'region', 'zaysan_ertis',
   'Водоёмы Павлодарской области', 'Павлодар облысының су айдындары', 'Waters of Pavlodar Region',
   'Сроки — как у водоёмов Восточно-Казахстанской области и области Абай, промысловая мера своя. Граница на карте — по границе области, приблизительно.',
   'Мерзімдері Шығыс Қазақстан және Абай облыстарының су айдындарындағыдай, кәсіптік өлшемі өзгеше. Картадағы шекара — облыс шекарасы бойынша, шамамен.',
   'Same dates as the waters of East Kazakhstan and Abai regions, with its own minimum sizes. The map follows the region boundary, approximately.',
   392),
  ('verkhnetobolsk', 'reservoir', 'tobyl_torgay',
   'Верхнетобольское водохранилище', 'Жоғарғы Тобыл су қоймасы', 'Verkhnetobolsk Reservoir',
   'Сроки — как у водоёмов Костанайской области, промысловая мера своя.',
   'Мерзімдері Қостанай облысының су айдындарындағыдай, кәсіптік өлшемі өзгеше.',
   'Same dates as the other waters of Kostanay Region, with its own minimum sizes.',
   612),
  ('karatomar', 'reservoir', 'tobyl_torgay',
   'Каратомарское водохранилище', 'Қаратомар су қоймасы', 'Karatomar Reservoir',
   'Сроки — как у водоёмов Костанайской области, промысловая мера своя.',
   'Мерзімдері Қостанай облысының су айдындарындағыдай, кәсіптік өлшемі өзгеше.',
   'Same dates as the other waters of Kostanay Region, with its own minimum sizes.',
   614);

