-- Прежние зоны без вырезанного: область не накрывает водоёмы и другие области со своими правилами.
-- Обрезки меньше 1 км² отброшены.
update public.rule_zones z
   set geom = (select extensions.st_multi(extensions.st_collect(d.geom))
                 from extensions.st_dump(extensions.st_collectionextract(extensions.st_makevalid(
                        extensions.st_snaptogrid(extensions.st_difference(z.geom, (
                          select extensions.st_union(o.geom) from public.rule_zones o
                           where o.id = any (case z.id when 'irtysh_east_waters' then array['pavlodar_waters']
                                                       else array['verkhnetobolsk', 'karatomar'] end))),
                        0.00001)), 3)) d
                where extensions.st_area(d.geom::extensions.geography) > 1e6)
 where z.id in ('irtysh_east_waters', 'kostanay_waters');

update public.rule_zones
   set name_ru = 'Водоёмы Восточно-Казахстанской области и области Абай',
       name_kk = 'Шығыс Қазақстан және Абай облыстарының су айдындары',
       name_en = 'Waters of East Kazakhstan and Abai regions'
 where id = 'irtysh_east_waters';

update public.rule_zones
   set note_ru = 'Кроме Аркалыка, Амангельдинского и Джангельдинского районов (у них свои сроки) и Верхнетобольского и Каратомарского водохранилищ (у них своя промысловая мера). Граница на карте — по границе области, приблизительно.',
       note_kk = 'Арқалық, Амангелді және Жангелдин аудандарынан (олардың өз мерзімдері бар) және Жоғарғы Тобыл мен Қаратомар су қоймаларынан (олардың өз кәсіптік өлшемі бар) басқа. Картадағы шекара — облыс шекарасы бойынша, шамамен.',
       note_en = 'Except Arkalyk and the Amangeldy and Zhangeldy districts (their own dates) and the Verkhnetobolsk and Karatomar reservoirs (their own minimum sizes). The map follows the region boundary, approximately.'
 where id = 'kostanay_waters';

-- Запреты прежних зон действуют и в новых (до того, как добавлены меры: у мер зоны свои).
update public.regulations
   set zone_ids = zone_ids || '{pavlodar_waters}'
 where 'irtysh_east_waters' = any (zone_ids);

update public.regulations
   set zone_ids = zone_ids || '{verkhnetobolsk,karatomar}'
 where 'kostanay_waters' = any (zone_ids);

-- Промысловая мера ---------------------------------------------------------------------------------

insert into public.regulations
  (id, kind, basin, zone_ids, gear, start_month, start_day, end_month, end_day, min_sizes,
   title_ru, title_kk, title_en, body_ru, body_kk, body_en,
   source_title, source_url, source_clause, verified_on, sort_order)
values
  ('min_size_shardara', 'min_size', 'aral_syrdarya',
   '{shardara,shardara_rest}', 'all', null, null, null, null,
   '{"common_carp": 35, "zander": 38, "grass_carp": 45, "silver_carp": 45, "wels_catfish": 65, "sabrefish": 31, "asp": 31}',
